import {randomUUID} from 'node:crypto';
import {createDatabase,seed,getSnapshot,postSetupCommand,postCommand,postRecipe,postMenuItem} from '@saas/server';
import type {Access} from '@saas/contracts';
import {createPOSCart} from '../../packages/domain/pos';
export async function counterPOSFixture(path?:string){const db=await createDatabase(path),org='grills',now=()=>new Date().toISOString(),access:Access={organizationId:org,userId:'test-cashier',deviceId:randomUUID(),expiresAt:new Date(Date.now()+86400000).toISOString()};await seed(db,'moving_average',false);const setup=async(type:string,record:unknown)=>postSetupCommand(db,access,{organizationId:org,operationId:randomUUID(),type,expectedRevision:0,record,capturedAt:now(),schemaVersion:1});await setup('unit.save',{id:'kg',name:'كجم'});await setup('location.save',{id:'main',name:'المخزن الرئيسي',kind:'مخزن',active:true});for(const id of ['rice','pepper'])await setup('item.save',{id,name:id==='rice'?'أرز':'توابل',sku:id,category:'مواد غذائية',unitId:'kg',minimum:'0',purchaseUnits:[],active:true});for(const id of ['k1','k2']){await setup('kitchen.save',{id,name:id==='k1'?'المطبخ البحري':'المطبخ القبلي',locationId:id,parentLocationId:'main',active:true});await setup('pos.save',{id:'p'+id.slice(1),name:id==='k1'?'كاشير البحري':'كاشير القبلي',source:'POS',kitchenId:id,active:true});for(const itemId of ['rice','pepper'])await postCommand(db,access,{operationId:randomUUID(),organizationId:org,type:'receipt.post',locationId:id,itemId,quantity:id==='k1'?'2':'10',unitCost:'10',reason:'Isolated POS fixture',businessDate:'2026-10-10',capturedAt:now(),schemaVersion:1});}
 const recipeId=randomUUID(),versionId=randomUUID(),base={organizationId:org,recipeId,capturedAt:now(),schemaVersion:1};await postRecipe(db,access,{...base,operationId:randomUUID(),expectedRevision:0,type:'recipe.save',definition:{code:'MEAL',name:'وجبة أرز',outputMode:'non_stocked',outputQuantity:'1',outputUnitId:'kg',effectiveDate:'2026-10-10',salesStockItemIds:['rice'],lines:['rice','pepper'].map(id=>({lineId:randomUUID(),kind:'material',itemId:id,unitId:'kg',inputUnit:'base',enteredQuantity:'1',quantity:'1'}))}});await postRecipe(db,access,{...base,operationId:randomUUID(),expectedRevision:1,type:'recipe.publish',versionId});const menuId=randomUUID();await postMenuItem(db,access,{operationId:randomUUID(),organizationId:org,type:'menu.save',expectedRevision:0,record:{id:menuId,source:'POS',code:'MEAL',name:'وجبة أرز',versionId,outputPerSale:'1',kitchenIds:['k1','k2'],active:true,sellingPrice:'80.25',category:'وجبات'},capturedAt:now(),schemaVersion:1});
 const snapshot=await getSnapshot(db,access);function cart(quantity='1',pos='p1'){const c=createPOSCart(snapshot,pos),menu=snapshot.menuItems![0];return {...c,lines:[{lineId:randomUUID(),menuItemId:menu.id,menuCode:menu.code,menuName:menu.name,mappingRevision:menu.revision,versionId:menu.versionId,outputPerSale:menu.outputPerSale,quantity,unitPrice:menu.sellingPrice!,note:'بدون ملح'}]};}return {db,access,snapshot,cart,menuId};}
